+interface EventKindOptionsInput {
+	connectors: ConnectorEventKindSource[];
+	entityTypes: EntityEventKindSource[];
+	selectedPlatforms?: string[];
+	selectedEntityTypes?: string[];
+}
+
+function objectRecord(value: unknown): Record<string, unknown> | null {
+	return value && typeof value === "object" && !Array.isArray(value)
+		? (value as Record<string, unknown>)
+		: null;
+}
+
+function connectorEventKinds(
+	connector: ConnectorEventKindSource,
+	selectedEntityTypes?: Set<string>,
+) {
+	const kinds = new Set<string>();
+
+	for (const feed of Object.values(connector.feeds_schema ?? {})) {
+		const feedKinds = objectRecord(objectRecord(feed)?.eventKinds);
+		if (!feedKinds) continue;
+
+		for (const [kind, schema] of Object.entries(feedKinds)) {
+			if (!selectedEntityTypes) {
+				kinds.add(kind);
+				continue;
+			}
+
+			const attributions = objectRecord(schema)?.attributions;
+			if (!Array.isArray(attributions)) continue;
+			if (
+				attributions.some((attribution) => {
+					const target = objectRecord(objectRecord(attribution)?.target);
+					return (
+						typeof target?.entityType === "string" &&
+						selectedEntityTypes.has(target.entityType)
+					);
+				})
+			) {
+				kinds.add(kind);
+			}
+		}
+	}
+
+	return kinds;
+}
+
+/**
+ * Build the Kind filter catalog from the same registries that validate writes.
+ * Connector selection is the strongest source constraint. Entity browsing adds
+ * the entity's own kinds and connector kinds explicitly attributed to it.
+ */
+export function collectRelevantEventKinds({
+	connectors,
+	entityTypes,
+	selectedPlatforms = [],
+	selectedEntityTypes = [],
+}: EventKindOptionsInput): string[] {
+	const kinds = new Set<string>();
+	const platformSet = new Set(selectedPlatforms);
+	const entityTypeSet = new Set(selectedEntityTypes);
+
+	if (platformSet.size > 0) {
+		for (const connector of connectors) {
+			if (!platformSet.has(connector.key)) continue;
+			for (const kind of connectorEventKinds(connector)) kinds.add(kind);
+		}
+	} else if (entityTypeSet.size > 0) {
+		for (const entityType of entityTypes) {
+			if (!entityTypeSet.has(entityType.slug)) continue;
+			for (const kind of Object.keys(entityType.event_kinds ?? {})) {
+				kinds.add(kind);
+			}
+		}
+
